    pub fn scene(&self, id: SceneId) -> Result<SceneView<'_>> {
        let i = self.index(id)?;
        Ok(self.scenes[i].view(
            self.owner,
            i,
            &self.scenes,
            &self.source,
            self.animation.view(),
            self.ignored,
